      introPassTT: ["Welcome to {track}! Eight kilometres of mountain road, just you and the clock.", "Here we are above El Castaño. {cps} checkpoints between you and the top.", "Welcome to {track}! No rivals this time, only the clock and the hairpins."],
      goPassTT: ["Green light! The clock is running!", "Go! Attack the climb!", "And you're away! Up into the cloud forest!"],
      introTraffic: ["Welcome to {track}, and the road is open today: cars, minibuses and motorbikes both ways! Just you and {rival}, first to the top wins!", "Here we are on the road to the coast. A duel with {rival} through the traffic. Mind the minibuses in the hairpins!"],
      introPolice: ["Welcome to {track}! The police want a word with you, and they are right behind. Get to the top without getting caught!", "Here we are above El Castaño, and the lights are already flashing. Eight kilometres of hairpins. Do not stop!"],
      escaped: ["You made it to the top! The police will have to wait for another day!", "Escaped! Up through the forest and away!"],
      summitRecord: ["At the top! A new personal best, {time}!", "Record run! {time} up from El Castaño!", "What a climb! New personal best, {time}!"],
      summitEven: ["At the top in {time}. That is your record to the thousandth!", "{time} at the finish, dead level with your best!"],
      summit: ["At the top in {time}, {delta} seconds off your best.", "Across the line in the cloud forest. {time}, just {delta} short of the record.", "That's El Castaño. {time}. {delta} seconds to find next time."],
